import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const kiBurstCard='a2-p09-r3c2';
export const kiBurstScenarios=['ki-burst-ordinary','ki-burst-owner-ordinary','ki-burst-low','ki-burst-dedicated','ki-burst-far','ki-burst-same-faction','ki-burst-water','ki-burst-equal','ki-burst-lower','ki-burst-gad-ordinary','ki-burst-gad-decline','ki-burst-gad-dedicated','ki-burst-gad-maai','ki-burst-gad-water','ki-burst-maai-one-ordinary','ki-burst-maai-two-ordinary','ki-burst-maai-one-dedicated','ki-burst-maai-two-dedicated','ki-burst-evade-ordinary','ki-burst-evade-dedicated','ki-burst-fate','ki-burst-suppressed','ki-burst-silenced','ki-burst-stopped','ki-burst-wrong-owner','ki-burst-decline','ki-burst-noncounter','ki-burst-white-prohibited','ki-burst-before-dedicated','ki-burst-after-dedicated','ki-burst-target-before-dedicated','ki-burst-target-after-dedicated'] as const;
export type KiBurstScenario=typeof kiBurstScenarios[number];
export function isKiBurstScenario(name:string):name is KiBurstScenario{return (kiBurstScenarios as readonly string[]).includes(name);}
export function kiBurstMode(name:KiBurstScenario){const suffix=name.replace('ki-burst-',''),dedicated=!(suffix.includes('ordinary')||['low','gad-decline','decline','white-prohibited'].includes(suffix)),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary'||suffix==='gad-ordinary'||suffix==='gad-decline',gad=suffix.startsWith('gad-'),follower=suffix==='water'||suffix==='gad-water'?'a2-p23-r1c1':suffix==='equal'?'a2-p20-r2c2':suffix==='lower'?'a2-p19-r1c3':null,freeze=suffix.includes('before-')||suffix.includes('after-'),after=suffix.includes('after-'),target=suffix.startsWith('target-');return {suffix,dedicated,owner,gad,follower,freeze,after,target};}
export function makeKiBurstPhysical(name:KiBurstScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=kiBurstMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.suffix==='white-prohibited'?'不死王ガドューラ':m.owner?'大神官ジル':'侍大将のシン',m.gad?'不死王ガドューラ':'黒騎士ガーウィン','小人のランバ','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?11:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?3:m.dedicated?0:4))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,kiBurstCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c1')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.suffix.startsWith('maai')||m.suffix==='gad-maai')keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.suffix.startsWith('evade'))keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`KI_BURST_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('KI_BURST_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('KI_BURST_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('KI_BURST_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('KI_BURST_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
